import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './CSS/ContactMessages.css'; // Optional styling file

const ContactMessages = () => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchMessages();
  }, []);

  const fetchMessages = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:4000/api/admin/contacts');
      if (response.data.success) {
        setMessages(response.data.contacts);
      } else {
        setError('Failed to fetch messages.');
      }
    } catch (err) {
      console.error('Error fetching contact messages:', err);
      setError('Server error while loading messages.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-messages-container" style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#0f172a' }}>Customer Messages</h2>
        <button 
          onClick={fetchMessages} 
          style={{ padding: '8px 16px', backgroundColor: '#130352', color: '#fff', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}
        >
          Refresh
        </button>
      </div>

      {loading ? (
        <p>Loading customer inquiries...</p>
      ) : error ? (
        <p style={{ color: '#ef4444' }}>{error}</p>
      ) : messages.length === 0 ? (
        <p>No messages received yet.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {messages.map((msg) => (
            <div 
              key={msg._id} 
              style={{
                backgroundColor: '#ffffff',
                border: '1px solid #e2e8f0',
                borderRadius: '12px',
                padding: '20px',
                boxShadow: '0 2px 4px rgba(0,0,0,0.02)'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #f1f5f9', pb: '10px', marginBottom: '12px' }}>
                <div>
                  <strong style={{ fontSize: '16px', color: '#1e293b' }}>{msg.name}</strong>
                  <span style={{ fontSize: '14px', color: '#64748b', marginLeft: '10px' }}>({msg.email})</span>
                </div>
                <span style={{ fontSize: '12px', color: '#94a3b8' }}>
                  {new Date(msg.createdAt).toLocaleString()}
                </span>
              </div>

              <div style={{ marginBottom: '8px' }}>
                <strong style={{ color: '#475569', fontSize: '14px' }}>Subject: </strong>
                <span style={{ color: '#0f172a', fontWeight: '600', fontSize: '14px' }}>{msg.subject}</span>
              </div>

              <div style={{ backgroundColor: '#f8fafc', padding: '12px', borderRadius: '8px', color: '#334155', fontSize: '14px', lineHeight: '1.5', whiteSpace: 'pre-wrap' }}>
                {msg.message}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ContactMessages;
